/**
 * Stand-in for SvelteKit's `$app/env/private` under vitest.
 *
 * The runtime module is generated by `svelte-kit sync` and only resolves inside a SvelteKit build,
 * so importing any server module that reads configuration would fail here on the import alone -
 * which is why `src/lib/auth.ts` had no unit test at all. Nothing in this stub is a fixture: no
 * variable is declared, so `#lib/server/env.ts` copies an empty object, and a test that needs one
 * sets it on that object (or replaces the module with `vi.mock`). A code path that reads an
 * undeclared variable then breaks loudly instead of passing on a made-up value.
 */
export {};
